    /// SPEC-CONSTITUTION §13: the active constitution must be exportable,
    /// diffable, and *self-contained*. It previously rendered clause statements
    /// grouped by kind and nothing else — no version, no provenance, no
    /// controls, no waivers — so a reviewer handed the file could not tell which
    /// policy it was, where a clause came from, what enforced it, or which
    /// exceptions were live. It could not be audited from, which is the only
    /// reason the export exists.
    #[test]
    fn an_export_carries_the_policy_a_reviewer_would_need_to_audit_it() {
        let e = engine();
        let draft = reviewed_draft(&e);
        e.activate_constitution(&draft, "monk-eee").unwrap();

        let exported = e.export_constitution(None).unwrap();

        assert!(exported.contains("## Version"), "{exported}");
        assert!(
            exported.contains(&draft),
            "the export names its own version"
        );
        assert!(exported.contains("Activated by: monk-eee"), "{exported}");
        assert!(exported.contains("## Active waivers"), "{exported}");
        assert!(exported.contains("- Provenance:"), "{exported}");
        assert!(exported.contains("- Consequence:"), "{exported}");
        assert!(exported.contains("- Waivable:"), "{exported}");
        assert!(exported.contains("Control"), "{exported}");
    }

    /// §13's first property: a repository with no constitution is reported as
    /// ungoverned and never silently judged. An export that simply omitted the
    /// version would read exactly like a governed project whose clauses happen
    /// to be few.
    #[test]
    fn an_ungoverned_repository_exports_as_ungoverned() {
        let e = engine();

        let exported = e.export_constitution(None).unwrap();

        assert!(
            exported.contains("No active constitution (state: Absent)"),
            "{exported}"
        );
    }

    /// The migration that creates the first version invents neither rationale
    /// nor authority (§12.1 task 1), so purpose and preamble are legitimately
    /// empty. Omitting them would render that indistinguishable from a document
    /// that dropped the fields — the reader must be able to tell "nobody wrote
    /// one" from "the export lost it".
    #[test]
    fn an_absent_preamble_is_reported_rather_than_quietly_omitted() {
        let e = engine();
        let draft = reviewed_draft(&e);
        e.activate_constitution(&draft, "monk-eee").unwrap();

        let exported = e.export_constitution(None).unwrap();

        assert!(exported.contains("- Purpose: _not recorded_"), "{exported}");
        assert!(
            exported.contains("- Preamble: _not recorded_"),
            "{exported}"
        );
    }

    /// §13: valid waivers are scoped, attributed, expiring, and *present in the
    /// audit*. An exception nobody can see from the policy document is an
    /// exception nobody reviews.
    ///
    /// The clause is built rather than borrowed from the Common Core, because
    /// no Common Core clause declares itself waivable — a fact worth stating
    /// here so the next reader does not assume the fixture is arbitrary.
    #[test]
    fn a_live_waiver_appears_in_the_export_so_exceptions_are_auditable() {
        let e = engine();
        let clause = e
            .define_goal(GoalKind::Constraint, "Reviewed", "Merge by review.", None)
            .unwrap();
        e.store
            .set_goal_status_for_test(&clause.id, GoalStatus::Draft)
            .unwrap();
        e.complete_clause_contract(
            &clause.id,
            "artifact:crates/**",
            "review evidence",
            Some(Consequence::Block),
            true,
            Some("maintainer"),
        )
        .unwrap();
        e.store
            .set_goal_status_for_test(&clause.id, GoalStatus::Active)
            .unwrap();

        let waiver = e
            .grant_waiver(&crate::waiver::WaiverRequest {
                clause_id: clause.id.clone(),
                scope: "artifact:crates/lodestar-core/**".to_string(),
                reason: "migration in flight".to_string(),
                approved_by: "maintainer".to_string(),
                expires_at: now_unix() + 3_600,
                remediation_task_id: None,
            })
            .unwrap();

        let exported = e.export_constitution(None).unwrap();

        assert!(exported.contains(&waiver.id), "{exported}");
        assert!(exported.contains("migration in flight"), "{exported}");
    }

    #[test]
    fn a_clause_gains_the_power_to_block_only_through_an_explicit_contract() {
        // SPEC-CONSTITUTION §10: migration invents no scope, evidence, or
        // consequence, so a clause is review-only until someone completes the
        // contract. Before this method existed there was no supported way to do
        // it at all — the enforcement machinery was unreachable, and every
        // active clause in a migrated project stayed permanently inert.
        let e = engine();
        let draft = e
            .define_goal(
                GoalKind::Invariant,
                "No secrets",
                "Never commit keys.",
                None,
            )
            .unwrap();
        e.store
            .set_goal_status_for_test(&draft.id, GoalStatus::Draft)
            .unwrap();
        assert!(draft.scope.is_none());
        assert!(draft.consequence.is_none());

        let completed = e
            .complete_clause_contract(
                &draft.id,
                "artifact:crates/**",
                "secret scan",
                Some(Consequence::Block),
                true,
                Some("security-team"),
            )
            .unwrap();

        assert_eq!(completed.scope.as_deref(), Some("artifact:crates/**"));
        assert_eq!(completed.consequence, Some(Consequence::Block));
        assert!(completed.waivable);
        assert_eq!(completed.waiver_authority.as_deref(), Some("security-team"));
    }

    #[test]
    fn hardening_an_active_clause_is_refused_as_an_amendment() {
        // Moving a clause from review-only to block changes what governs
        // everyone already working under it. ADR-0039 fixed the shape of that
        // act: draft, diff, rationale. A direct edit here would be precisely the
        // quiet amendment that diff exists to expose.
        let e = engine();
        let active = e
            .define_goal(
                GoalKind::Invariant,
                "No secrets",
                "Never commit keys.",
                None,
            )
            .unwrap();
        assert_eq!(active.status, GoalStatus::Active);

        let error = e
            .complete_clause_contract(
                &active.id,
                "artifact:crates/**",
                "secret scan",
                Some(Consequence::Block),
                false,
                None,
            )
            .unwrap_err();
        assert!(format!("{error}").contains("is an amendment"), "{error}");
    }

