    #[test]
    fn an_ungoverned_project_reaches_a_cited_draft_without_activating() {
        // SPEC-CONSTITUTION §7.3 + task 3 acceptance: a fixture repository with
        // no constitution reaches a cited draft, every Common Core clause is
        // left undecided, and nothing activates itself.
        let e = engine();
        let paths = [
            "README.md".to_string(),
            "AGENTS.md".to_string(),
            ".github/workflows/ci.yml".to_string(),
            "CODEOWNERS".to_string(),
        ];
        let proposal = e.propose_constitution(&paths, Some("maintainer")).unwrap();

        assert_eq!(proposal.version.status, GoalStatus::Draft);
        assert_eq!(proposal.version.id, "constitution:v1");
        assert_eq!(proposal.facts.len(), 4);
        assert!(proposal.facts.iter().all(|f| !f.source_path.is_empty()));
        assert_eq!(proposal.common_core.proposals.len(), 5);
        assert!(proposal
            .common_core
            .proposals
            .iter()
            .all(|p| p.disposition.is_none()));

        // The draft governs nothing: status stays draft, not active.
        let status = e.constitution_status().unwrap();
        assert_eq!(status.state, ConstitutionState::Draft);
        // Facts are durable provenance, not a transient response.
        assert_eq!(e.constitution_facts(&proposal.version.id).unwrap().len(), 4);
    }

